  guideSlug: "hand-knotted-vs-machine-made-rugs",
  guideTitle: "Hand-Knotted vs Machine-Made Rugs: How to Tell and What It Is Worth",
  metaTitle: "Hand-Knotted vs Machine-Made Rugs",
  metaDescription: "Learn to read the back of a rug, count knot density, tell hand-tufted from hand-knotted and judge value over years instead of at the checkout.",
  heroImage: "/images/articles/knotted-rug-hero.webp",
